/* A OnePage's unpublished blocks private to the public key (round AX, run any time). WHY: the policy "Anyone reads a published onepage" lets the anon key, which is in every page Storelib serves, read every column of every published OnePage through the REST API, onepages.draft_blocks (the owner's unpublished edits) and archived_blocks (blocks they removed) included; row level security cannot hide a column. The app reads OnePages for visitors with the service role (lib/onepage/published-page, app/(storelib)/(marketing)/l/[slug]) and reads only id and slug when the proxy falls back to the anon key, so no reader in the app needs these two columns from the anon key. WHAT IT DOES: when the anon key can read draft_blocks or archived_blocks, takes SELECT on public.onepages from anon and gives SELECT back on every other column, so the published columns still answer the anon key and the two private ones are refused (permission denied); a column added later is private to anon until granted. It does NOT change any row or policy, does not change what a signed in account reads (the owner's editor reads its own page with select * on its own session, so the same grant for authenticated would break it; a signed in stranger reading another page's draft is listed as still open in docs/reliability/SECURITY.md), and does not change INSERT, UPDATE or DELETE. Takes a short lock on the table. A missing table or column is skipped with a notice. Safe to run again: a second run finds nothing the anon key can read and changes nothing. To check: select has_column_privilege('anon', 'public.onepages', 'draft_blocks', 'SELECT'); */
DO $do$ DECLARE cols text; private text[]; BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 464: public.onepages does not exist here, skipped'; RETURN; END IF; SELECT array_agg(c.column_name::text) INTO private FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = 'onepages' AND c.column_name IN ('draft_blocks', 'archived_blocks'); IF private IS NULL THEN RAISE NOTICE 'part 464: public.onepages has no draft_blocks or archived_blocks here, skipped'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM unnest(private) s WHERE has_column_privilege('anon', 'public.onepages', s, 'SELECT')) THEN RAISE NOTICE 'part 464: the anon key already cannot read %', private; RETURN; END IF; SELECT string_agg(format('%I', a.attname), ', ' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid = 'public.onepages'::regclass AND a.attnum > 0 AND NOT a.attisdropped AND NOT (a.attname::text = ANY (private)); EXECUTE 'REVOKE SELECT ON public.onepages FROM anon'; EXECUTE format('GRANT SELECT (%s) ON public.onepages TO anon', cols); IF EXISTS (SELECT 1 FROM unnest(private) s WHERE has_column_privilege('anon', 'public.onepages', s, 'SELECT')) THEN RAISE WARNING 'part 464: the anon key still reads % through a grant to PUBLIC; revoke it by hand after checking who uses it', private; ELSE RAISE NOTICE 'part 464: the anon key no longer reads %', private; END IF; END $do$;
notify pgrst, 'reload schema';
